    class Webhooks
      def initialize(client)
        @c = client
      end

      # Create a webhook endpoint
      #
      # Subscribes a public HTTPS URL to events from the catalog (see the webhooks section of this document). The signing secret is in the response and is shown only once. Private and loopback addresses are refused.
      #
      # Needs a session, or an API key or OAuth token with the `webhooks:write` scope.
      def create_webhook(body, idempotency_key: nil, timeout: nil)
        @c.request(:post, '/v1/webhooks', path_params: {  }, query: {  }, timeout: timeout, body: body, idempotent: true, idempotency_key: idempotency_key, type: 'WebhookSecretResponse')
      end

      # Delete a webhook endpoint
      #
      # Stops deliveries to this endpoint and removes it.
      #
      # Needs a session, or an API key or OAuth token with the `webhooks:write` scope.
      def delete_webhook(id, timeout: nil)
        @c.request(:delete, '/v1/webhooks/{id}', path_params: { 'id' => id }, query: {  }, timeout: timeout, type: 'Ok')
      end

      # List deliveries
      #
      # Shows an endpoint's delivery attempts with status and response codes. Cursor paginated.
      #
      # Needs a session, or an API key or OAuth token with the `webhooks:read` scope.
      def list_webhook_deliveries(id, cursor: nil, limit: nil, timeout: nil)
        @c.request(:get, '/v1/webhooks/{id}/deliveries', path_params: { 'id' => id }, query: { 'cursor' => cursor, 'limit' => limit }, timeout: timeout, type: 'ListWebhookDeliveriesResponse')
      end

      # Enumerates every item of #list_webhook_deliveries, fetching pages as needed.
      def list_webhook_deliveries_iter(id, cursor: nil, limit: nil, timeout: nil)
        @c.paginate(:get, '/v1/webhooks/{id}/deliveries', path_params: { 'id' => id }, query: { 'cursor' => cursor, 'limit' => limit }, timeout: timeout, type: 'WebhookDeliveryDto')
      end

      # List webhook endpoints
      #
      # Lists the organization's endpoints and the events each subscribes to. Signing secrets are never returned here.
      #
      # Needs a session, or an API key or OAuth token with the `webhooks:read` scope.
      def list_webhooks(cursor: nil, limit: nil, timeout: nil)
        @c.request(:get, '/v1/webhooks', path_params: {  }, query: { 'cursor' => cursor, 'limit' => limit }, timeout: timeout, type: 'ListWebhooksResponse')
      end

      # Enumerates every item of #list_webhooks, fetching pages as needed.
      def list_webhooks_iter(cursor: nil, limit: nil, timeout: nil)
        @c.paginate(:get, '/v1/webhooks', path_params: {  }, query: { 'cursor' => cursor, 'limit' => limit }, timeout: timeout, type: 'WebhookEndpointDto')
      end

      # Replay a delivery
      #
      # Sends a past delivery's payload again with a fresh signature. The event id stays the same, so receivers still deduplicate.
      #
      # Needs a session, or an API key or OAuth token with the `webhooks:write` scope.
      def replay_webhook_delivery(id, idempotency_key: nil, timeout: nil)
        @c.request(:post, '/v1/webhook-deliveries/{id}/replay', path_params: { 'id' => id }, query: {  }, timeout: timeout, idempotent: true, idempotency_key: idempotency_key, type: 'WebhookDeliveryDto')
      end

      # Rotate a signing secret
      #
      # Issues a new secret, shown once. For 24 hours deliveries carry signatures from both the old and the new secret, so receivers can switch without dropping events.
      #
      # Needs a session, or an API key or OAuth token with the `webhooks:write` scope.
      def rotate_webhook_secret(id, idempotency_key: nil, timeout: nil)
        @c.request(:post, '/v1/webhooks/{id}/rotate-secret', path_params: { 'id' => id }, query: {  }, timeout: timeout, idempotent: true, idempotency_key: idempotency_key, type: 'WebhookSecretResponse')
      end

      # Send a test event
      #
      # Queues a signed webhook.test delivery to this endpoint so you can check your receiver and signature code.
      #
      # Needs a session, or an API key or OAuth token with the `webhooks:write` scope.
      def test_webhook(id, idempotency_key: nil, timeout: nil)
        @c.request(:post, '/v1/webhooks/{id}/test', path_params: { 'id' => id }, query: {  }, timeout: timeout, idempotent: true, idempotency_key: idempotency_key, type: 'WebhookDeliveryDto')
      end

      # Update a webhook endpoint
      #
      # Changes an endpoint's URL, events, filters, payload version, template or active state.
      #
      # Needs a session, or an API key or OAuth token with the `webhooks:write` scope.
      def update_webhook(id, body, timeout: nil)
        @c.request(:patch, '/v1/webhooks/{id}', path_params: { 'id' => id }, query: {  }, timeout: timeout, body: body, type: 'WebhookEndpointDto')
      end

    end

